/* Six reviewed loops; Newton/Tesla methods and U endpoint evidence. */
(() => {
  'use strict';
  const prior=window.ResearchObservatory,D=window.ROUND23_DATA;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const route=(id,label)=>`<a href="#research/${id}">${esc(label)}</a>`;
  const source=(path,label)=>`<a href="https://github.com/occult-kranti/yang_mills_workbench/blob/main/${esc(path)}">${esc(label)} ↗</a>`;
  const solo=x=>x.independence.independent_agents===false;
  const nav=()=>`<nav class="rc-nav" aria-label="Round23 research navigation">${route('home','Current results')}${route('round23-u2','Endpoint finding')}${route('research-methods','Newton & Tesla')}${route('round23-roadmap','Roadmap & handoff')}${route('round22-home','Round22 archive')}</nav>`;
  const status=x=>(x.status==='limited'?'Limited result':'Accepted within scope')+(solo(x)?' · single-agent self-review':' · prior independent-agent review');
  const links=x=>`<div class="r22-evidence">${source(`research/round23/contracts/${x.loop}.json`,'Frozen contract')}${source(`research/round23/forward/${x.loop}/report.md`,'Derivation')}${source(`research/round23/reverse/${x.loop}/report.md`,solo(x)?'Same-author obligation audit':'Reverse derivation')}${source(`research/round23/skeptic/${x.loop}.md`,solo(x)?'Critical self-review':'Skeptical review')}${source(`research/round23/advisor/${x.loop}-gate.json`,'Evidence gate')}</div>`;
  function card(x){return `<article class="rc-result"><p class="rc-kicker">${esc(x.loop.toUpperCase())} · ${esc(status(x))}</p><h2>${esc(x.claim)}</h2><p>${esc(x.scope)}</p>${route('round23-'+x.loop,'Read result, scope and evidence →')}</article>`;}
  function mechanism(){return `<figure class="r23-mechanism"><svg viewBox="0 0 580 310" role="img" aria-labelledby="u-graph-title u-graph-desc"><title id="u-graph-title">Eight-link resonance mechanism</title><desc id="u-graph-desc">Three edge-disjoint paths connect O at 3,1,0 to D at 3,2,1. X and Y have two links; Z has four. X and Y form the omitted yz plaquette. The two six-link loops share the Z return path.</desc><g fill="none" stroke-width="3"><path d="M55 150 L290 48 L525 150" stroke="#2c6570"/><path d="M55 150 L290 252 L525 150" stroke="#986b2c"/><path d="M55 150 L170 150 L290 150 L410 150 L525 150" stroke="#555c61"/></g><g fill="#fbfaf7" stroke="#333" stroke-width="2">${[[55,150],[525,150],[290,48],[290,252],[170,150],[290,150],[410,150]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="6"/>`).join('')}</g><g fill="currentColor" font-size="15" text-anchor="middle"><text x="55" y="180">O</text><text x="525" y="180">D</text><text x="290" y="25">X · 2 links</text><text x="290" y="287">Y · 2 links</text><text x="290" y="132">Z · 4 links</text><text x="154" y="72">y</text><text x="423" y="72">z</text><text x="154" y="239">z</text><text x="423" y="239">y</text></g></svg><figcaption>Schematic, not a metric drawing. All eight links are actual free reference factors. The two loop states use XZ⁻¹ and YZ⁻¹; the resonant face uses XY⁻¹.</figcaption></figure>`;}
  // Ratios can contain >308 decimal digits. Scale mantissas before converting.
  const num=x=>{const [n,d='1']=String(x).split('/');const part=s=>{const neg=s[0]==='-',v=neg?s.slice(1):s,k=Math.min(v.length,15);return {m:Number(v.slice(0,k))*(neg?-1:1),e:v.length-k};};const a=part(n),b=part(d);return (a.m/b.m)*10**(a.e-b.e);};
  const sci=x=>num(x).toExponential(3);
  function certificates(){return `<section class="rc-section"><h2>A finite-q certificate you can inspect</h2><p>Fixed η = 1/2 and C = 1/500000, so Cη = 10⁻⁶. Values are rounded displays of exact rational enclosures. This is a lower-bound calculation, not a simulated correlation trajectory.</p><div class="r23-table-wrap"><table class="r23-table"><caption>Certified error estimate at T = C(ℏ/α)ε⁻³</caption><thead><tr><th scope="col">ε = 1 − q</th><th scope="col">Leading signal</th><th scope="col">Bulk upper bound</th><th scope="col">State upper bound</th><th scope="col">Error lower estimate</th></tr></thead><tbody>${D.endpoint_certificates.map(r=>`<tr><th scope="row">${sci(r.epsilon)}</th><td>${sci(r.leading)}</td><td>${sci(r.bulk_upper)}</td><td>${sci(r.state_upper)}</td><td>${num(r.difference_lower)>0?`<strong>${sci(r.difference_lower)}</strong>`:`${sci(r.difference_lower)}<br><small>Inconclusive</small>`}</td></tr>`).join('')}</tbody></table></div><p>The endpoint limit has certified lower bound ${sci(D.liminf_lower_at_cap)} at Cη = 10⁻⁶. A negative finite-q estimate makes this certificate inconclusive; it does not imply a negative error or convergence.</p>${source('research/round23/forward/u2/output/results.json','Exact rational values and square-root enclosures')}</section>`;}
  function roadmap(){return `<header class="r22-page-head"><p class="rc-kicker">Stop after U2 · 6/10 reviewed</p><h1>The next loops are planned, not started.</h1><p>The requested U1/U2 pair is complete. V and W were selected after six reviewed S/T/U loops. They have no frozen contract, producer or gate.</p></header><section class="rc-section"><h2>V · operational observables and finite resolution</h2><p>V1 will ask whether an ordinary Wilson multiplication observable or a certified finite observable approximation retains an endpoint signal. Its error budget must hold on the same growing time window. Select V2 only after reviewing V1.</p><h2>W · residual and iteration closure</h2><p>W1 will revisit S’s filter residual and later-diagonal induction with complete support. Select W2 after W1 review. This is a different model obligation: U2 supplies no stability constants for it.</p><p>No next-loop execution is authorized by this completed run.</p>${source('research/round23/HANDOFF.md','Full next handoff')} · ${source('research/round23/advisor/current-roadmap.json','Machine-readable roadmap')}</section><section class="r22-limit"><h2>Open research obligations</h2><ul>${D.roadmap.open_parent_goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;}
  function home(){return `<section class="rc-hero"><div><p class="rc-kicker">Round23 · checkpoint through U2</p><h1>A local resonance survives the full-system error bound.</h1><p>The two requested loops are complete. U1 identifies the mechanism; U2 proves a positive endpoint correlation difference in the canonical summable model.</p><div class="rc-hero-actions">${route('round23-u2','Inspect the endpoint result →')}${route('research-methods','Explore Newton & Tesla →')}${route('round23-roadmap','Next handoff →')}</div></div><aside class="rc-score"><span class="rc-score-number">6<span>/ 10</span></span><strong>Investigations completed</strong><p>Four accepted within scope · two limited</p><small>Counts investigations, not the fraction of Yang–Mills solved.</small></aside></section><section class="r23-disclosure"><strong>U1 and U2 were completed by one agent.</strong><p>Advisor, derivations and skeptical passes share one author. This is critical self-review. Earlier independent-agent records are preserved. Scientific priority remains unverified; the four-dimensional continuum problem remains open.</p></section><section class="rc-section"><p class="rc-kicker">The new U2 statement</p><h2>An actual lower bound at the endpoint</h2><div class="r22-hero-equation">liminf |C<sub>q</sub>(T) − C<sub>0</sub>(T)| &gt; <span>Cη / 168</span> &gt; 0</div><p>For the fixed bounded gauge-invariant observable W, T = C(ℏ/α)(1−q)⁻³ and 0 &lt; Cη ≤ 10⁻⁶. The proof retains every connected interaction order and the ground-state error. W has nonzero variance; it is a local rank operator rather than a Wilson-loop multiplier.</p><p>This establishes one endpoint counterexample within the named model. It does not establish an exact trajectory, every observable’s behavior, or a continuum mass gap.</p></section><div class="rc-results rc-results-all">${D.loops.map(card).join('')}</div>`;}
  function methods(){return `<header class="r22-page-head"><p class="rc-kicker">Two installed research skills · project-wide guidance</p><h1>Imagination proposes.<br>Mathematics and evidence decide.</h1><p>A source-grounded study of Newton and Tesla now guides both advisor and skeptical passes. It covers mathematics, physics and esoteric interests while keeping their different kinds of claims visible.</p></header><div class="r23-method-grid"><article class="rc-result"><p class="rc-kicker">Newton · analysis and synthesis</p><h2>Reconstruct the cause, then test its consequences.</h2><p>Fluxions and inverse operations; geometric mechanics; optical experiments; weighed chymical trials; theological and prophetic symbolism.</p>${route('newton','Read the detailed Newton study →')}</article><article class="rc-result"><p class="rc-kicker">Tesla · mechanism and resonance</p><h2>Specify the mechanism, then include its loading.</h2><p>Phase geometry and circuit mathematics; motors, wireless and radiant-energy patents; Colorado notes; visualization; Vedantic correspondence and attributed esoteric writing.</p>${route('tesla','Read the detailed Tesla study →')}</article></div><section class="rc-section"><h2>How the skills changed this investigation</h2><ol><li><strong>U1:</strong> reconstruct an actual invariant observable and calculate its resonant coupling.</li><li><strong>Critical review:</strong> a nonzero leading term is insufficient without the full-system remainder.</li><li><strong>U2:</strong> count every connected interaction word and bound the error on the same clock.</li></ol><p>Both methods are used by the same author in advisor and skeptical roles. They are not claims that Newton or Tesla reviewed the work.</p><h2>Occult and esoteric material as research motivation</h2><p>Newton’s alchemy and theology, Tesla’s imaginative self-reports and documented Vedantic discussion, and later attributed claims receive separate source labels. A historical analogy can motivate a transformation, hidden variable or cycle. To enter the physics it needs an operational definition, a derivation and a falsifier.</p><p>The two studies contain twenty selected source entries plus archival routes. They state passages read, catalogued leads and weaker provenance. This is an expandable corpus, not a claim to have read every book, article or patent.</p>${source('research/methods/newton-tesla/README.md','Project-wide method guide')}</section>`;}
  function essay(id){const d=D.documents[id];return `<header class="r22-page-head"><p class="rc-kicker">Historical source study · ${esc(id)}</p><h1>${id==='newton'?'Newton: mathematics, physics and hidden causes.':'Tesla: mathematical mechanisms, imagination and esoteric claims.'}</h1><p>Selected primary sources and explicit modern reconstructions. Consulted 21 September 2026.</p>${route('research-methods','← Both research methods')}</header><article class="r23-essay">${d.html}</article><section class="rc-section">${source(d.path,'Source reference with reading limits')}<code class="r22-hash">Source SHA-256: ${esc(d.sha256)}</code></section>`;}
  function loopPage(x){return `<header class="r22-page-head"><p class="rc-kicker">Round23 · ${esc(x.loop.toUpperCase())}</p><h1>${esc(x.claim)}</h1><p>${esc(status(x))}</p></header><section class="rc-section"><h2>Supported statement</h2>${x.equations.map(e=>`<div class="r22-formula">${esc(e)}</div>`).join('')}<p>${esc(x.scope)}</p><p>${esc(x.target_verdict)}</p>${x.loop==='t2'?'<p>Each heat evolution uses its own calculated ground energy. At λ = 0.01 the all-time absolute upper bound 60λ² is 0.006.</p>':''}${links(x)}${x.loop.startsWith('u')?mechanism():''}<h2>Review and limits</h2><p>${esc(x.next_missing_premise)}</p><ul>${x.limits.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><details><summary>Authorship and verification</summary><pre>${esc(JSON.stringify(x.independence,null,2))}</pre></details><code class="r22-hash">Gate SHA-256: ${esc(x.gate_sha256)}</code>${D.documents[x.loop]?`<details class="r23-proof"><summary>Read the full mathematical derivation</summary><article class="r23-essay">${D.documents[x.loop].html}</article></details>`:''}<h2>Reproduce</h2><pre>python3 -B research/round23/reproduce.py --loops ${esc(x.loop)} --output /absolute/new/${esc(x.loop)}</pre><p>Scientific priority remains unverified. The continuum problem remains open.</p></section>${x.loop==='u2'?certificates():''}`;}
  const owns=r=>['home','contributions','round23-roadmap','research-methods','newton','tesla'].includes(r)||D.loops.some(x=>r==='round23-'+x.loop);
  function render(r='home'){
    if(r==='round22-home')return `<div class="rc-history-notice">Round22 release archive. ${route('home','Current six-loop checkpoint →')}</div>`+prior.render('home');
    if(!owns(r))return (r==='journey'||r==='round22-roadmap'?`<div class="rc-history-notice">Historical Round22 record. Round23 is now at 6/10; U2 supplies a scoped endpoint witness. ${route('round23-roadmap','Current roadmap →')}</div>`:'')+prior.render(r);
    const content=r==='round23-roadmap'?roadmap():r==='research-methods'?methods():r==='newton'||r==='tesla'?essay(r):r==='home'||r==='contributions'?home():loopPage(D.loops.find(x=>r==='round23-'+x.loop));
    return `<div class="rc20 r21 r22 r23">${nav()}${content}<footer class="rc-footer"><strong>Yang–Mills Workbench · Round23</strong>${source('research/round23/HANDOFF.md','Handoff')}${route('round23-roadmap','Roadmap')}</footer></div>`;
  }
  function afterRender(){const r=location.hash.split('/')[1]||'home';if(owns(r)){window.ResearchJourney?.cleanup?.();document.title='Round23 · '+(r==='round23-roadmap'?'Next handoff':r==='newton'?'Newton research':r==='tesla'?'Tesla research':'Research checkpoint')+' · Yang–Mills Workbench';}else{prior.afterRender();}}
  window.ResearchRound23={render,afterRender,data:D};
  window.ResearchObservatory={...prior,render,afterRender};
})();
